  "critique": [
    {
      "design": "r0A",
      "good": "The four equal quarterly columns keep values intact and establish a consistent comparison rhythm. The annual column has enough room for its heading and values. Row-label words remain intact.",
      "problems": "The long cost-of-revenue label occupies four lines, making that row much taller than the others. Q4 is only partly visible at first sight, and the annual total requires horizontal scrolling.",
      "cause": "The 145px label column leaves 124px for text; the 62px quarterly columns and 82px annual column preserve their contents but bring the table to 476px."
    },
    {
      "design": "r0B",
      "good": "The entire table fits in the viewport, and the four quarters retain equal widths. The annual heading wraps naturally between words.",
      "problems": "Numbers break across lines, making quarterly and annual values difficult to read and compare. Label words also split, and the resulting tall rows disrupt the relationship between labels and values.",
      "cause": "Each 49px quarterly column leaves only 28px for text, and the 53px annual column leaves 32px. The 110px label column leaves 89px, less than the width of its longest word."
    },
    {
      "design": "r0C",
      "good": "Labels are easy to read, the cost-of-revenue label occupies only two lines, and all values and headings remain intact. The shorter, more even rows make comparisons comfortable once the relevant columns are in view.",
      "problems": "The wide label column leaves only Q1 and part of Q2 visible initially. Readers must scroll substantially to compare the later quarters and annual total.",
      "cause": "The 250px label column consumes most of the viewport, while the intact numeric columns extend the table to 581px."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-labels",
      "widths": [175, 62, 62, 62, 62, 82],
      "change": "Widen the label column from r0A to reduce wrapping while retaining intact numbers and equal quarterly columns. This trades 30px of additional scrolling for more comfortable row labels."
    },
    {
      "name": "roomier-labels",
      "widths": [200, 62, 62, 62, 62, 82],
      "change": "Test an intermediate label width between r0A and r0C, seeking shorter label blocks without committing to r0C's full scrolling cost."
